const fs=require("fs"),crypto=require("crypto");
const P="/host/hermes-cron-ro/jobs.json",JOB="f5c0648122f3";
const read=()=>{try{return fs.readFileSync(P,"utf8");}catch(e){return null;}};
(async()=>{
  let raw=read();
  if(raw===null){await new Promise((r)=>setTimeout(r,300));raw=read();}
  const out={available:false,path:P,bytes:null,sha256:null,updated_at:null,job_found:false,job:null,reason:null};
  if(raw===null){out.reason="cron state file unreadable after one retry";}
  else{
    out.available=true;out.bytes=Buffer.byteLength(raw,"utf8");
    out.sha256=crypto.createHash("sha256").update(raw).digest("hex");
    try{
      const d=JSON.parse(raw);
      out.updated_at=typeof d.updated_at==="string"?d.updated_at:null;
      const j=(Array.isArray(d.jobs)?d.jobs:[]).find((x)=>x&&x.id===JOB)||null;
      if(j===null){out.reason="job "+JOB+" is not present in the cron state file";}
      else{
        out.job_found=true;
        const ld=j.last_dispatch,keys=["scheduled_at","dispatched_at","lateness_seconds","kind"],pd={};
        keys.forEach((k)=>{pd[k]=(ld&&typeof ld==="object"&&ld[k]!==undefined)?ld[k]:null;});
        out.job={job_id:j.id,name:j.name,enabled:j.enabled,state:j.state,schedule_display:j.schedule_display,last_run_at:j.last_run_at,last_status:j.last_status,last_error:j.last_error,failure_streak:j.failure_streak,next_run_at:j.next_run_at,last_dispatch:(ld&&typeof ld==="object")?pd:null};
      }
    }catch(e){out.job_found=false;out.reason="cron state file is not valid JSON";}
  }
  process.stdout.write(JSON.stringify(out)+"\n");
})();
'

